// ───────── 단위: 1m. 세그먼트 1개 = 1.5m, 도로 반폭 7.5m (3차선) ─────────
const SEG_M = 1.5, M = SEG_M / SEG, HALF_W = 7.5, WALL = HALF_W * 1.04, LAT_MAX = 6.7, HILL = M * .6;
const mobile = matchMedia('(pointer: coarse)').matches || innerWidth < 760;

// 도로 중심선: 커브 값을 누적해 실제 3D 곡선으로 (대기실 지도와 같은 계수)
const N = segs.length + 1;
const PX = new Float32Array(N), PZ = new Float32Array(N), PY = new Float32Array(N), ANG = new Float32Array(N);
{ let a = 0, x = 0, z = 0;
  for (let i = 0; i < N; i++) {
    PX[i] = x; PZ[i] = z; ANG[i] = a;
    PY[i] = (i < segs.length ? segs[i].p1.world.y : segs[i - 1].p2.world.y) * HILL;
    if (i < segs.length) { x += Math.cos(a) * SEG_M; z += Math.sin(a) * SEG_M; a += segs[i].curve * MAP_K; }
  } }
function frameAt(s) {   // s: 물리 거리 단위
  const f = Math.max(0, Math.min(N - 1.001, s / SEG)), i = Math.floor(f), t = f - i;
  return { x: PX[i] + (PX[i + 1] - PX[i]) * t, y: PY[i] + (PY[i + 1] - PY[i]) * t, z: PZ[i] + (PZ[i + 1] - PZ[i]) * t, a: ANG[i] + (ANG[i + 1] - ANG[i]) * t };
}
const right = a => new THREE.Vector3(-Math.sin(a), 0, Math.cos(a));
const fwd = a => new THREE.Vector3(Math.cos(a), 0, Math.sin(a));
function worldAt(s, lat, up = 0) { const p = frameAt(s); return new THREE.Vector3(p.x - Math.sin(p.a) * lat, p.y + up, p.z + Math.cos(p.a) * lat); }

// ───────── 렌더러·장면 ─────────
const canvas = document.createElement('canvas');
document.getElementById('race').prepend(canvas);
