const tex = (w, h, draw, repeat) => { const c = document.createElement('canvas'); c.width = w; c.height = h; draw(c.getContext('2d'), w, h); const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 8; if (repeat) { t.wrapS = t.wrapT = THREE.RepeatWrapping; } return t; };
const rnd = (() => { let s = 7; return () => (s = (s * 16807) % 2147483647) / 2147483647; })();

// 하늘: 노을 그라데이션 돔
const skyMat = new THREE.ShaderMaterial({ side: THREE.BackSide, depthWrite: false, fog: false, uniforms: {},
  vertexShader: 'varying vec3 vp; void main(){ vp = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.); }',
  fragmentShader: `varying vec3 vp; void main(){ float h = clamp(vp.y, -0.1, 1.0);
    vec3 top = vec3(${TH.sky[0]}), mid = vec3(${TH.sky[1]}), low = vec3(${TH.sky[2]}), hz = vec3(${TH.sky[3]});
    vec3 c = h < .04 ? mix(hz, low, h / .04) : h < .22 ? mix(low, mid, (h - .04) / .18) : mix(mid, top, (h - .22) / .78);
    gl_FragColor = vec4(c * .62, 1.); }` });   // 번짐 기준(1.0)보다 어둡게: 하늘은 번지지 않음
const sky = new THREE.Mesh(new THREE.SphereGeometry(10000, 32, 16), skyMat); scene.add(sky);

// 반사용 환경맵: 같은 노을 하늘 + 네온 띠
{ const env = new THREE.Scene(); env.add(new THREE.Mesh(new THREE.SphereGeometry(100, 32, 16), skyMat));
  const band = (c, y) => { const m = new THREE.Mesh(new THREE.CylinderGeometry(90, 90, 3, 32, 1, true), new THREE.MeshBasicMaterial({ color: c, side: THREE.BackSide })); m.position.y = y; env.add(m); };
  band(TH.bands[0], -6); band(TH.bands[1], -12); band(TH.bands[2], 4);
  const pm = new THREE.PMREMGenerator(renderer); scene.environment = pm.fromScene(env, .02).texture; }

scene.add(new THREE.HemisphereLight(...TH.hemi));
